                                                                                                                                                                                                                                                                                                                                    private void AtualizarLinhaAtual(long posicaoMs)
                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                    if (LetraAtual == null || !LetraAtual.Sincronizada) {
                                                                                                                                                                                                                                                                                                                                    LinhaAtual = null;
                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    TimeSpan posicaoAtual = TimeSpan.FromMilliseconds(posicaoMs);
                                                                                                                                                                                                                                                                                                                                    List<LinhaLetra> linhas = LetraAtual.Linhas;

                                                                                                                                                                                                                                                                                                                                        int inicio = 0;
                                                                                                                                                                                                                                                                                                                                        int fim = linhas.Count - 1;
                                                                                                                                                                                                                                                                                                                                        int indiceEncontrado = -1;

                                                                                                                                                                                                                                                                                                                                        while (inicio <= fim) {
                                                                                                                                                                                                                                                                                                                                           int meio = inicio + ( fim - inicio ) / 2;

                                                                                                                                                                                                                                                                                                                                        if (linhas[meio].Tempo <= posicaoAtual) {
                                                                                                                                                                                                                                                                                                                                           indiceEncontrado = meio;
                                                                                                                                                                                                                                                                                                                                           inicio = meio + 1;
                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                           else {
                                                                                                                                                                                                                                                                                                                                           fim = meio - 1;
                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                           LinhaLetra? linha = indiceEncontrado >= 0
                                                                                                                                                                                                                                                                                                                                            ? linhas[indiceEncontrado]
                                                                                                                                                                                                                                                                                                                                            : null;

                                                                                                                                                                                                                                                                                                                                            if (linha != LinhaAtual)
                                                                                                                                                                                                                                                                                                                                            LinhaAtual = linha;
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                            private void Shuffle(List<Music> list, Random rng, Music? primeira = null)
                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                int n = list.Count;
                                                                                                                                                                                                                                                                                                                                           while (n > 1) {
                                                                                                                                                                                                                                                                                                                                                    n--;
                                                                                                                                                                                                                                                                                                                                                    int k = rng.Next(n + 1);
                                                                                                                                                                                                                                                                                                                                                    (list[k], list[n]) = (list[n], list[k]);
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                    if (primeira == null) return;

                                                                                                                                                                                                                                                                                                                                           int i = list.FindIndex(m =>
                                                                                                                                                                                                                                                                                                                                                        string.Equals(m.Caminho, primeira.Caminho, StringComparison.OrdinalIgnoreCase));
                                                                                                                                                                                                                                                                                                                                                        if (i <= 0) return;

                                                                                                                                                                                                                                                                                                                                                           Music item = list[i];
                                                                                                                                                                                                                                                                                                                                                           list.RemoveAt(i);
                                                                                                                                                                                                                                                                                                                                                           list.Insert(0, item);
                                                                                                                                                                                                                                                                                                                                                           }

