                                                                                                                                                                                                                                                                                                                                                                                                                        musica ??= MusicaAtual;
                                                                                                                                                                                                                                                                                                                                                                                                                        if (musica == null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                        musica.Gosto = !musica.Gosto;
