                                                                                                                                                                                                                                                                                                                                                                                                                        if (parametro is not (Music musica, Playlist playlist)) return;

                                                                                                                                                                                                                                                                                                                                                                                                                        if (playlist.Name == "Favoritos") {
                                                                                                                                                                                                                                                                                                                                                                                                                        DatabaseService.AlternarGosto(musica.Caminho, true);
                                                                                                                                                                                                                                                                                                                                                                                                                        musica.Gosto = true;
