                                                                                                                                                                                                                                                                                                                                                                                                                        MusicaAtual.Gosto = true;
                                                                                                                                                                                                                                                                                                                                                                                                                        GostoAtual = true;
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                        int musicaId = DatabaseService.ObterIdMusicaPorCaminho(musica.Caminho);
                                                                                                                                                                                                                                                                                                                                                                                                                        if (musicaId != -1) {
                                                                                                                                                                                                                                                                                                                                                                                                                        DatabaseService.AdicionarMusicaAPlaylist(playlist.Id, musicaId);
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                        }

